UPDATE material_translations SET body='{"captions":["Emisfera continentală și emisfera oceanică ale Pământului","Cele patru oceane: Atlantic, Pacific (cu Groapa Marianelor), Indian și Arctic","Distribuția salinității apei oceanice pe glob","Variația în latitudine a temperaturii, salinității și densității apei oceanice","Golful Fundy (Canada) – aceleași stânci la maree înaltă (stânga) și la maree joasă (dreapta)","Mareele: maximă când Soarele, Luna și Pământul sunt aliniați – conjuncție (stânga); minimă când Luna și Soarele acționează în unghi drept – cuadratură (dreapta)","Harta curenților oceanici calzi și reci","Pârâul, râul și fluviul – deosebiri de mărime a albiei","Elementele unui râu (izvor, curs, bazin hidrografic, afluent, cumpăna apelor, gura de vărsare)","Formele de apă din scoarța terestră – apa de suprafață și apele subterane din porii și fisurile rocilor","Gheizer – apă subterană fierbinte care țâșnește la suprafață (ape termale)","Banchiză – gheață formată din apa mării, la țărm","Aisberg – bloc de gheață desprins din calotă, cu partea vizibilă și cea submersă","Schema formării banchizei și a aisbergurilor la marginea calotei glaciare"]}' WHERE material_id='b5f18c1a-c936-464b-9b0e-e4d40e67247f' AND locale='ro';
